<template><section class="card"><h1>로그인</h1><form class="form" @submit.prevent="submit"><div class="field"><label>아이디</label><input v-model="form.username" required></div><div class="field"><label>비밀번호</label><input v-model="form.password" type="password" required></div><button>로그인</button><p v-if="error" class="error">{{error}}</p></form></section></template>
<script setup>import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAccountStore } from '@/stores/account'; const router=useRouter(); const store=useAccountStore(); const form=reactive({username:'',password:''}); const error=ref(''); const submit=async()=>{try{await store.logIn(form); router.push({name:'HomeView'})}catch(e){error.value='아이디 또는 비밀번호를 확인해주세요.'}}</script>
